    {"id": "hub_b2_vendor_review", "cefr_level": "B2", "domain": "professional", "title_es": "Evaluación de proveedor", "title_en": "Quarterly Vendor Review", "subtitle_es": "Revisa SLA, tiempos de entrega y renegocia metas realistas", "opening_en": "Appreciate joining our QBR. Missed SLAs spiked in October—how do you plan to tighten turnaround without hurting quality?", "opening_es": "Gracias por la revisión trimestral. Subieron fallos en octubre: ¿cómo planean ajustar entregas sin bajar calidad?", "starter_suggestions": ["Fair question—we noticed handoff bottlenecks that are fairly straightforward to streamline.", "Looking back, we should have scaled weekend coverage ahead of seasonal peaks.", "Unless response times stay under four hours, credit rebates apply automatically."], "icon_name": "handshake", "focus_skill_es": "Gestión de proveedores B2", "coach_intro_es": "Combina modales pasados ('should have scaled') y condicional claro ('Unless...')."},

    {"id": "hub_c1_research_defense", "cefr_level": "C1", "domain": "academic", "title_es": "Defensa metodológica de tesis", "title_en": "Methodology Defense Q&A", "subtitle_es": "Explica límites de muestra y evita exagerar hallazgos", "opening_en": "Your longitudinal findings look compelling, yet how do you defend sample selection against self-selection bias?", "opening_es": "Tus hallazgos longitudinales convencen, pero ¿cómo defiendes la muestra frente a sesgo de autoselección?", "starter_suggestions": ["A critical caveat: our data suggest correlation among volunteers, pending broader randomized replication.", "To mitigate distortion, we benchmarked baseline traits against national census cohorts.", "Notwithstanding sample bounds, the trend remained consistent across three waves."], "icon_name": "school", "focus_skill_es": "Defensa académica C1", "coach_intro_es": "Aplica hedging disciplinado ('suggest', 'pending') y concesión ('Notwithstanding')."},
    {"id": "hub_c1_board_reorg", "cefr_level": "C1", "domain": "professional", "title_es": "Alineación tras reestructura", "title_en": "Post-Reorg Leadership Sync", "subtitle_es": "Reconstruye confianza entre áreas y alinea métricas claras", "opening_en": "Following last month's restructuring, cross-functional morale feels fragile. How will you get product and sales back on the same page?", "opening_es": "Tras la reestructura, la moral entre áreas está frágil. ¿Cómo alineas de nuevo a producto y ventas?", "starter_suggestions": ["What matters most right now is anchoring weekly standups around shared customer outcomes.", "Seldom do teams align through memos alone; joint discovery calls rebuild rapport quickly.", "Once ownership boundaries stay unambiguous, momentum returns steadily."], "icon_name": "executive", "focus_skill_es": "Liderazgo ejecutivo C1", "coach_intro_es": "Usa 'What matters most...', inversión ('Seldom do...') y vocabulario C1 ('rapport')."},

    {"id": "hub_c2_peer_review_panel", "cefr_level": "C2", "domain": "academic", "title_es": "Simposio interdisciplinario C2", "title_en": "Interdisciplinary Symposium", "subtitle_es": "Cuestiona falsas dicotomías y defiende rigor epistémico", "opening_en": "Several commentators frame algorithmic governance as a binary choice between innovation velocity and public safety. Do you accept that dichotomy?", "opening_es": "Varios plantean la gobernanza algorítmica como disyuntiva binaria entre rapidez y seguridad. ¿Aceptas esa dicotomía?", "starter_suggestions": ["That dichotomy proves spurious: brittle haste creates downtime that erodes adoption far faster than prudent oversight.", "Were institutions to standardize verifiable audit trails, speed and accountability would reinforce one another.", "Scarcely had open benchmarks matured when responsible teams outpaced opaque competitors."], "icon_name": "psychology", "focus_skill_es": "Debate académico C2", "coach_intro_es": "Desmonta falsas dicotomías con subjuntivo invertido y precisión conceptual."},
    {"id": "hub_c2_cross_border_ma", "cefr_level": "C2", "domain": "professional", "title_es": "Mediación en fusión internacional", "title_en": "Cross-Border Merger Counsel", "subtitle_es": "Concilia culturas corporativas distintas con subtexto y tacto C2", "opening_en": "London leadership read Munich's cautious memo as passive resistance, whereas Munich feared reckless rushing. How do you bridge that pragmatic divide?", "opening_es": "Londres leyó el memorando prudente de Múnich como resistencia pasiva y Múnich temió prisa temeraria. ¿Cómo salvas la brecha?", "starter_suggestions": ["Both sides spoke past one another partly because understated caution sounded tantamount to rejection.", "Let us decouple shared retention milestones from stylistic candor, lest cultural friction stall integration.", "Each side ought to articulate non-negotiable guardrails explicitly rather than relying on subtext."], "icon_name": "globe", "focus_skill_es": "Diplomacia corporativa C2", "coach_intro_es": "Combina pragmática intercultural ('understated', 'tantamount to') y 'lest'."},
